  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  final GlobalKey<CurrencyListPageState> _currencyKey = GlobalKey();
  final GlobalKey<NewsListPageState> _newsKey = GlobalKey();

  bool _isRefreshing = false;

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  Future<void> refreshAll() async {
    if (_isRefreshing) return;

    setState(() => _isRefreshing = true);

    final CurrencyListPageState? currencyState = _currencyKey.currentState;
    final NewsListPageState? newsState = _newsKey.currentState;

    await Future.wait(<Future<void>>[
      (currencyState?.refreshData() ?? Future.value()),
      (newsState?.refreshData() ?? Future.value()),
    ]);

    if (mounted) {
      setState(() => _isRefreshing = false);
    }
  }

  Widget _buildCurrentPage() {
    switch (_selectedIndex) {
      case 0:
        return CurrencyListPage(key: _currencyKey);
      case 1:
        return NewsListPage(key: _newsKey);
      default:
        return ProfilePage();
    }
  }

  String _getAppBarTitle() {
    switch (_selectedIndex) {
      case 0:
        return context.loc.currencyRate;
      case 1:
        return context.loc.news;
      default:
        return context.loc.profile;
    }
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final bool isCurrencyTab = _selectedIndex == 0;
    final bool isNewsTab = _selectedIndex == 1;

    return Scaffold(
      appBar: AppBar(title: Text(_getAppBarTitle())),
      body: RefreshIndicator(
        onRefresh: refreshAll,
        child: _buildCurrentPage(),
      ),
