        onPressed: _isRefreshing ? null : refreshAll,
        icon: AnimatedRotation(
          turns: _isRefreshing ? 0.5 : 0,
          duration: const Duration(milliseconds: 400),
          child: Icon(_isRefreshing ? Icons.sync_rounded : Icons.sync),
        ),
        label: Text(loc.updateAll),
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
